(6505764, 967292, 108580, '<td valign="top">Super Cool - Is it a reactor? :) Stunning colours and very vibrant, neon glow is also hard to capture properly. Well done.</td>', 'Super Cool - Is it a reactor? :) Stunning colours and very vibrant, neon glow is also hard to capture properly. Well done.', '2011-08-16 03:41:40.000000', NULL, 1),
(6505765, 967447, 108580, '<td valign="top">Unique and ballsy for DPC, seascape abstract art, bumped +1.</td>', 'Unique and ballsy for DPC, seascape abstract art, bumped +1.', '2011-08-16 03:48:03.000000', NULL, 1),
(6505767, 966832, 108580, '<td valign="top">Very unique and gutsy for a DPC entry. Nice idea! It appears a wee bit off in the sharpness dept, could have had a lot more seeing as it''s a studio shot.</td>', 'Very unique and gutsy for a DPC entry. Nice idea! It appears a wee bit off in the sharpness dept, could have had a lot more seeing as it''s a studio shot.', '2011-08-16 03:51:18.000000', NULL, 1),
(6505771, 967238, 108580, '<td valign="top">Super shot, love the blurred grass movement in the BG and fawn colours.</td>', 'Super shot, love the blurred grass movement in the BG and fawn colours.', '2011-08-16 03:57:56.000000', NULL, 1),
(6505831, 967118, 108580, '<td valign="top">This could easily be a Tanguera shot. Jo''s B&amp;W &amp; studio work is showing some serious promise. If not then the compliment still stands. The exposure &amp; contrast is top notch, starting with an interesting arrangement of subjects legs, handbag, side table (crop a bit tight) &amp; wooden floor. Very nice.</td>', 'This could easily be a Tanguera shot. Jo''s B&W & studio work is showing some serious promise. If not then the compliment still stands. The exposure & contrast is top notch, starting with an interesting arrangement of subjects legs, handbag, side table (crop a bit tight) & wooden floor. Very nice.', '2011-08-16 06:20:09.000000', NULL, 1),
(6505841, 967211, 126903, '<td valign="top"><u></u></td>', '', '2011-08-16 07:37:09.000000', NULL, 1),
(6505890, 967126, 132515, '<td valign="top">I like this picture, but it would be nice to see the toad in color.  I think B/W takes away from this.</td>', 'I like this picture, but it would be nice to see the toad in color.  I think B/W takes away from this.', '2011-08-16 11:29:08.000000', NULL, 1),
